// Home Health Aide Practice Test 2. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items, with different home care situations from Practice Test 1.
import {q, mix} from './q.js';
const BAL='Balduzzi, Homemaker Home Health Aide', HART='Leahy, Fuzy & Grafe, Providing Home Care';
const RESP='Responsibilities and Legal/Ethical Issues', COMM='Effective Communication', INF='Infection Control and Safety', BODY='Body Systems and Common Disorders', SPEC='Caring for Special Populations', SKILL='Basic Healthcare Skills';

export default {
 id:'home-health-aide-2',
 event:'Home Health Aide',
 title:'Practice Test 2',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Balduzzi’s Homemaker Home Health Aide and Leahy, Fuzy & Grafe’s Providing Home Care',
 plan:[{area:RESP,weight:10},{area:COMM,weight:6},{area:INF,weight:10},{area:BODY,weight:40},{area:SPEC,weight:24},{area:SKILL,weight:10}],
 questions:mix([
  q(RESP,'A client asks the aide to cut her toenails. She has diabetes. What should the aide do?','Decline and tell the nurse',['Cut them straight across','Cut them very short','File them down to the skin'],'B','Aides do not cut the nails of clients with diabetes or poor circulation because small cuts can lead to serious infection.',HART),
  q(RESP,'Which federal law gives Medicare clients the right to be informed about their care and to refuse treatment?','The Patient Self-Determination Act',['The Fair Labor Standards Act','The Clean Air Act','The Social Security Act of 1935'],'D','It requires agencies to inform clients of their rights, including advance directives.',HART),
  q(RESP,'A client’s son asks the aide to sign as a witness on his mother’s new will. What should the aide do?','Politely decline',['Sign it to be helpful','Sign it only if paid','Sign the son’s name instead'],'A','Aides should not witness legal documents for clients because of possible conflicts of interest.',HART),
  q(RESP,'Which is an example of neglect?','Leaving a client soiled for hours',['Helping a client bathe each day','Reporting a fall','Following the care plan'],'C','Neglect is failing to provide needed care. Aides must report signs of neglect or abuse.',HART),
  q(RESP,'An aide makes an error when documenting care on paper. How should it be corrected?','Cross out once and initial',['Erase it completely','Use correction fluid','Tear out the page'],'B','The original entry must remain readable. Follow agency policy for electronic records.',HART),
  q(COMM,'What is the best way to communicate with a client who has a hearing aid?','Face the client and speak clearly',['Speak into the hearing aid','Shout every word','Talk while turned away'],'D','Reduce background noise, check that the hearing aid is on and the battery works.',HART),
  q(COMM,'Which is a barrier to communication?','Giving unrequested advice',['Using open-ended questions','Restating the client’s words','Showing interest by nodding'],'A','Advice, clichés and changing the subject can make clients feel unheard.',HART),
  q(COMM,'A client from another culture avoids eye contact. What should the aide do?','Respect it as a norm',['Insist on eye contact','Assume the client is lying','Report the client as rude'],'C','Cultural norms about eye contact, touch and personal space differ. Avoid judging.',HART),
  q(INF,'Which is the best way to clean a client’s bathroom to prevent infection?','Clean from cleanest to dirtiest areas',['Use the same cloth for the toilet first','Clean only once a month','Skip gloves for speed'],'B','Clean the sink and tub before the toilet so germs are not spread.',HART),
  q(INF,'Where should cleaning products be stored in a home with a confused client?','In a locked or high cabinet',['Under the kitchen sink','On the counter','In food containers'],'D','Locked storage prevents accidental poisoning. Never store chemicals in food containers.',HART),
  q(INF,'Which practice prevents falls in the home?','Removing throw rugs',['Using dim lighting at night','Keeping cords across walkways','Waxing floors to a high shine'],'A','Night lights, grab bars, clear paths and nonslip shoes also reduce the risk of falls.',HART),
  q(INF,'How should food be stored to prevent foodborne illness?','Refrigerate leftovers within 2 hours',['Leave cooked food out overnight','Store raw meat above vegetables','Thaw meat on the counter'],'C','Bacteria grow quickly between 40 °F and 140 °F, the temperature danger zone.',HART),
  q(INF,'What should an aide do in a home fire?','Get the client out, then call 911',['Gather belongings first','Open all windows','Hide in a closet with the client'],'B','Leave quickly, stay low under smoke and never go back inside.',HART),
  q(BODY,'Which condition causes thin, brittle bones that break easily?','Osteoporosis',['Osteoarthritis','Gout','Bursitis'],'D','Calcium, vitamin D, weight-bearing exercise and fall prevention help protect bones.',HART),
  q(BODY,'What should the aide do if a client with diabetes is sweating, shaky and confused?','Give fast-acting sugar if able to swallow',['Give an insulin shot','Have the client lie down to sleep','Give nothing by mouth'],'A','These are signs of low blood sugar. Report to the supervisor after giving juice or glucose.',HART),
  q(BODY,'A client with Parkinson disease has trouble starting to walk. What helps?','Cueing a rhythm or count',['Pulling the client forward','Rushing the client','Keeping the client in bed'],'C','Rhythmic cues can help overcome “freezing.” Remove clutter that could cause falls.',HART),
  q(BODY,'Which sign of a stroke should be reported immediately?','One-sided weakness',['A mild cold','Gradual hair loss','Dry skin'],'B','Use BE FAST and call 911. Note when the symptoms started, since treatment depends on timing.',HART),
  q(BODY,'What is the main symptom of angina?','Chest pain with exertion',['A sudden rash','Pain only in the toes and feet','Blurred vision only'],'D','Angina usually occurs with exertion and is relieved by rest or nitroglycerin.',HART),
  q(BODY,'Which practice helps a client with COPD conserve energy?','Sitting while doing tasks',['Rushing through tasks','Lying flat often','Skipping meals'],'A','Spacing activities, rest breaks and pursed-lip breathing also help.',HART),
  q(BODY,'What does a client with kidney failure need to limit?','Fluid, potassium and salt',['Fiber and whole grains only','Fruit and fruit juices only','Vitamin C and folate only'],'C','Failing kidneys cannot remove fluid and electrolytes well. Follow the care plan’s diet orders.',HART),
  q(BODY,'A client has a urinary catheter. Which observation should be reported?','Cloudy urine with blood',['Pale yellow urine','About 1,500 mL per day','Tubing free of kinks'],'B','Cloudy or bloody urine, fever and pain may signal a catheter-associated urinary tract infection.',HART),
  q(BODY,'Which symptom is common in a client with hypothyroidism?','Fatigue and cold intolerance',['Weight loss and anxiety','Fast heart rate','Heat intolerance'],'D','Low thyroid hormone slows metabolism, causing fatigue, weight gain and feeling cold.',HART),
  q(BODY,'Why should a client with glaucoma use prescribed eye drops every day?','To lower eye pressure',['To cure cataracts','To improve hearing','To clear the sinuses'],'A','Untreated glaucoma damages the optic nerve and causes permanent vision loss.',HART),
  q(BODY,'A client with arthritis has trouble opening jars. What can help?','Adaptive equipment',['Ignoring the problem','Doing it for them every time','Eliminating jarred foods'],'C','Assistive devices promote independence. An occupational therapist can recommend tools.',HART),
  q(BODY,'Which symptom suggests a client may be dehydrated?','Dark urine and dry mouth',['Pale urine and moist skin','Weight gain','Swollen ankles'],'B','Encourage fluids as allowed and report signs of dehydration, especially in older adults.',HART),
  q(BODY,'A client with heart failure gains 4 pounds in 2 days. What does this suggest?','Fluid retention',['Better appetite','Muscle gain','Improved health'],'D','Rapid weight gain is a sign of fluid buildup. Weigh at the same time each day and report changes.',HART),
  q(BODY,'Which is a common side effect of radiation therapy for cancer?','Fatigue',['Improved energy','Hair growth','Increased appetite'],'A','Do not wash off treatment markings, and use mild soap on the treated area.',HART),
  q(BODY,'Which digestive problem is a common side effect of opioid pain medicine?','Constipation',['Diarrhea','Heartburn only','Excess hunger'],'C','Fluids, fiber, activity and prescribed stool softeners help prevent it.',HART),
  q(BODY,'Which sign may indicate a pressure injury is forming?','Redness that does not fade',['Normal skin color','Soft, warm skin','Pale skin that quickly pinks'],'B','Report redness that does not fade. Reposition the client at least every 2 hours.',HART),
  q(BODY,'What should an aide do for a client with a nosebleed?','Lean forward and pinch',['Tilt the head back','Lay the client flat','Pack the nose with cotton'],'D','Leaning forward keeps blood out of the throat. Pinch for 10 minutes.',HART),
  q(BODY,'Which symptom suggests pneumonia in an older adult?','New confusion',['Increased energy','Clear lungs','Better appetite'],'A','Older adults may not have a high fever. Report changes in breathing or mental status.',HART),
  q(BODY,'What is the main concern for a client with emphysema receiving too much oxygen?','It may reduce the drive to breathe',['It cures emphysema','It causes high blood sugar','It always causes fever'],'C','Never change oxygen settings. Only the nurse or physician can change the flow rate.',HART),
  q(BODY,'A client with hepatitis B lives at home. How is it spread?','Blood and body fluids',['Casual hugging','Sharing dishes only','Coughing'],'B','Use standard precautions and do not share razors or toothbrushes.',HART),
  q(SPEC,'What is the best way to help a client with dementia eat?','Serve one food at a time',['Serve many foods at once','Rush the meal','Use a busy, noisy room'],'D','Simple choices and a calm setting reduce confusion and increase intake.',HART),
  q(SPEC,'How should an aide respond to a client with dementia who accuses her of stealing?','Stay calm and help search',['Argue and prove innocence','Leave the home','Call the police at once'],'A','Accusations are often caused by memory loss. Report the behavior to the supervisor.',HART),
  q(SPEC,'Which is a normal sign of approaching death?','Mottled, cool hands and feet',['Rising blood pressure','Stronger appetite','Faster recovery'],'C','Breathing changes, decreased urine and less responsiveness are also common.',HART),
  q(SPEC,'What should an aide do after a client dies at home under hospice care?','Notify the supervisor',['Call 911 immediately','Begin CPR','Move the body to the bed'],'B','Hospice clients usually have DNR orders. The agency directs the next steps.',HART),
  q(SPEC,'Which is a safe practice for a newborn in the home?','Support the head when lifting',['Prop the bottle in the crib','Put soft toys in the crib','Leave the baby on a bed alone'],'D','Newborns cannot hold up their heads. Never leave them unattended on raised surfaces.',HART),
  q(SPEC,'How should a baby’s formula be warmed?','In a bowl of warm water',['In the microwave','On the stove until it boils','Left out overnight'],'A','Microwaves heat unevenly and create hot spots that can scald the baby’s mouth.',HART),
  q(SPEC,'Which is a sign of postpartum depression that should be reported?','Lasting sadness',['Brief tearfulness on day 3','Mild tiredness','Normal appetite'],'C','“Baby blues” are short. Persistent sadness, anxiety or thoughts of harm need help.',HART),
  q(SPEC,'A client with a mental illness refuses to take a prescribed medicine. What should the aide do?','Report it to the supervisor',['Hide the medicine in food','Force the client to take it','Ignore it'],'B','Clients have the right to refuse. The supervisor or nurse decides what to do next.',HART),
  q(SPEC,'Which approach helps a child adjust to a home health aide?','Explain care simply and honestly',['Use complex medical terms','Avoid talking to the child','Tell the child it never hurts'],'D','Involve parents and allow the child to make simple choices when possible.',HART),
  q(SPEC,'A client with a developmental disability wants to make her own sandwich. What should the aide do?','Let her do it with support',['Do it for her','Tell her it is unsafe','Make it while she watches'],'A','Promoting independence builds confidence and skills, even if the task takes longer.',HART),
  q(SPEC,'Which is a warning sign of elder abuse?','Fear of a caregiver',['Regular visits by family','Clean clothes','Steady weight'],'C','Unexplained injuries, weight loss and fear may signal abuse. Aides are required to report it.',HART),
  q(SPEC,'What helps a client with a new disability adjust to life at home?','Focus on what they can still do',['Do everything for them','Avoid discussing the disability','Limit all visitors'],'D','Encouragement, independence and focusing on abilities support emotional well-being after a disability.',HART),
  q(SKILL,'What is the correct way to measure an axillary temperature?','In the dry armpit, arm held down',['Under the tongue, lips closed','Hold it against the forehead','Place it in the ear canal'],'A','Axillary readings are about 1 °F lower than oral readings; leave the thermometer in place as directed.',HART),
  q(SKILL,'Which bed position is used when a client has trouble breathing?','Fowler’s position',['Trendelenburg','Prone','Flat supine'],'C','Raising the head of the bed 45–60 degrees lets the lungs expand and eases breathing.',HART),
  q(SKILL,'What should an aide do before helping a client out of bed?','Lock the wheels and dangle the legs',['Lift the client without warning','Leave the bed raised high','Use a slippery sheet underfoot'],'B','Dangling allows blood pressure to adjust and prevents dizziness.',HART),
  q(SKILL,'What is the best way to help a client who uses a walker?','Stand behind on the weak side',['Walk in front of the client','Pull the walker forward','Hold the client’s arms up'],'D','Use a gait belt as needed and make sure the walker’s legs are level.',HART),
  q(SKILL,'How many mL are in an 8-oz glass of water?','240 mL',['80 mL','160 mL','300 mL'],'A','1 oz = 30 mL, so 8 × 30 = 240 mL. Record fluid intake accurately.',HART)
 ],1009)
};
